Dùng thuật toán SX SelectionSort để SX List
void SelectionSort(LIST &l)
{
Node *p,*q,*min;
p=l.pHead;
while(p!=l.pTail)
{
min=p;
q=p->pNext;
while(q!=NULL)
{
if(q->Info<p->Info)
min=q;
q=q->pNext;
}
HV(min->Info,p->Info);
p=p->pNext;
}
}

